// Playwright hides scrollbars by default. Visible ones take layout space, as on a Windows desktop.
const HIDE_SCROLLBARS = '--hide-scrollbars';
export const Scrollbars = { hidden: 'hidden', visible: 'visible' } as const;
type ScrollbarMode = (typeof Scrollbars)[keyof typeof Scrollbars];
// A busy verifier runs many browsers at once, so a single wait gets more than Playwright's 5s default.
export const expect = playwrightExpect.configure({ timeout: 15_000 });
// Most journeys fit the standard limit. The accessibility journey and the large boards take the long one.
export const TestTimeouts = { standard: 30_000, long: 90_000 } as const;
// npm names itself and its version to every script it runs, so a browser file needs no npm process of its own.
const NPM_AGENT_ENV = 'npm_config_user_agent';
let browser: Browser | undefined;
let scrollbarBrowser: Promise<Browser> | undefined;
let artifact: Awaited<ReturnType<typeof serveArtifact>> | undefined;

before(async () => {
  await mkdir(BROWSER_TEMP, { recursive: true });
  await mkdir(RESULTS, { recursive: true });
  process.env.TEMP = BROWSER_TEMP;
  process.env.TMP = BROWSER_TEMP;
  const npm = /^npm\/(\S+)/.exec(process.env[NPM_AGENT_ENV] ?? '')?.[1] ?? npmVersion();
  const playwright: unknown = JSON.parse(
    await readFile(new URL(import.meta.resolve('@playwright/test/package.json')), 'utf8'),
  );
  assert.ok(playwright && typeof playwright === 'object' && 'version' in playwright);
  browser = await launch(Scrollbars.hidden);
  const runtime = {
    node: process.versions.node,
    npm,
    playwright: String(playwright.version),
    chromium: browser.version(),
  };
  const named = process.env[NAMED_COMBINATION_ENV] === '1';
  await writeFile(
    join(RESULTS, 'browser-runtime.json'),
    JSON.stringify({ ...runtime, namedCombination: named }, null, 2),
  );
  if (named) assert.deepEqual(runtime, NAMED_COMBINATION, 'T03 named combination');
  artifact = await serveArtifact();
});

after(async () => {
  await browser?.close();
  await (await scrollbarBrowser)?.close();
  await artifact?.close();
});

function launch(scrollbars: ScrollbarMode): Promise<Browser> {
  const executable = process.env[EXECUTABLE_ENV];
  return chromium.launch({
    headless: true,
    ...(executable ? { executablePath: executable } : {}),
    ...(scrollbars === Scrollbars.visible ? { ignoreDefaultArgs: [HIDE_SCROLLBARS] } : {}),
  });
}

interface BrowserFixture {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  gameURL: string;
}
interface Artifacts {
  outputPath(file: string): string;
}

function npmVersion(): string {
  const npmResult =
    process.platform === 'win32'
      ? spawnSync('cmd.exe', ['/d', '/c', 'npm --version'], { encoding: 'utf8' })
      : spawnSync('npm', ['--version'], { encoding: 'utf8' });
  assert.equal(npmResult.status, 0, 'T03 npm version command');
  return npmResult.stdout.trim();
}

export function test(
  name: string,
  body: (fixture: BrowserFixture, artifacts: Artifacts) => Promise<void>,
  options: BrowserContextOptions = {},
  scrollbars: ScrollbarMode = Scrollbars.hidden,
  timeout: number = TestTimeouts.standard,
): void {
  nodeTest(name, { timeout }, async (t) => {
    if (!browser || !artifact) throw new Error('Browser verification did not start.');
    const owner =
      scrollbars === Scrollbars.visible ? await (scrollbarBrowser ??= launch(scrollbars)) : browser;
    const context = await owner.newContext(options);
    t.after(() => context.close());
    const page = await context.newPage();
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));
    const directory = join(RESULTS, name.replace(/[^a-z0-9]+/gi, '-'));
    await mkdir(directory, { recursive: true });
    const artifacts = {
      outputPath(file: string): string {
        if (basename(file) !== file) throw new Error('Expected an artifact filename.');
        return join(directory, file);
      },
    };
    await body({ browser: owner, context, page, gameURL: artifact.url }, artifacts);
    assert.deepEqual(pageErrors, []);
  });
}

import { readFile } from 'node:fs/promises';
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('status formats show current values, continuing minutes and a completed import without Resume', async ({
  page,
}) => {
  const initial: string[] = [];
  await loadTimedBoard(page);
  // Rendered text shows whether each value sits on its label's line.
  const status = () =>
    page.locator('.stats > div').evaluateAll((elements) =>
      elements.map((element) => {
        if (!(element instanceof HTMLElement)) throw new Error('Expected a rendered status.');
        return element.innerText;
      }),
    );
  initial.push(...(await status()));
  for (const index of EXAMPLE_PAIRS[0]) await page.locator('.card').nth(index).click();
  const matched = await status();
  await page.locator('summary').click();
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      matched: EXAMPLE_PAIRS.flat(),
      selection: { kind: 'closed' },
      moves: 8,
      elapsedMs: 3_600_999,
      started: true,
    }),
  );
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  const loaded = await status();
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toHaveCount(0);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.load-notice')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.victory.celebrate')).toHaveCount(0);
  await page.clock.runFor(2000);
  expect(await status()).toEqual(loaded);
  const expected: unknown = JSON.parse(
    await readFile(new URL('./status-format.fixture.json', import.meta.url), 'utf8'),
  );
  expect({ initial, matched, loaded }).toEqual(expected);
});

test('the Board code control trims surrounding whitespace and both successful load types select their size', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const board = page.getByLabel(ReproductionControl.board, { exact: true });
  await board.fill('  np1-6-1  ');
  await board.press('Enter');
  await expect(board).toHaveValue('np1-6-1');
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  await expect(page.locator('.card')).toHaveCount(36);
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-8-1',
      matched: [],
      selection: { kind: 'closed' },
      moves: 0,
      elapsedMs: 0,
      started: false,
    }),
  );
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('8');
  await expect(page.locator('.card')).toHaveCount(64);
  await expect(
    page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
  ).toBeVisible();
});

test('named color targets, reset margins and card focus scroll margins follow the visual contract', async ({
  page,
}) => {
  await loadTimedBoard(page);
  for (const selector of [
    '.board-viewport',
    '.reproduction',
    'button',
    'select',
    'input',
    'textarea',
  ]) {
    await expect(page.locator(selector).first()).toHaveCSS('background-color', 'rgb(20, 24, 39)');
  }
  await expect(page.locator('body')).toHaveCSS('margin', '0px');
  for (const selector of ['.eyebrow', '.help', '.intro', '.stats dt']) {
    const secondary = page.locator(selector).first();
    await expect(secondary, `V08 secondary size ${selector}`).toHaveCSS('font-size', '14px');
    await expect(secondary, `V06 secondary color ${selector}`).toHaveCSS(
      'color',
      'rgb(184, 189, 210)',
    );
  }
  const card = page.locator('.card').nth(EXAMPLE_PAIRS[0][0]);
  const margin = await card.evaluate((element) => getComputedStyle(element).scrollMargin);
  expect(parseFloat(margin)).toBeGreaterThanOrEqual(6);
  await card.hover();
  await page.clock.runFor(120);
  await expect(card).toHaveCSS('border-color', 'rgb(244, 246, 255)');
  await card.click();
  const main = card.locator('svg g');
  const marker = card.locator('svg > circle');
  await expect(main).toHaveAttribute('fill', '#63E7FF');
  await expect(marker).toHaveAttribute('fill', '#63E7FF');
  await expect(marker).toHaveAttribute('stroke', 'var(--face)');
  await page.locator('.card').nth(EXAMPLE_PAIRS[0][1]).click();
  await card.hover();
  await page.clock.runFor(120);
  await expect(card).toHaveCSS('border-color', 'rgb(139, 234, 125)');
  await expect(card.locator('.matched-mark')).toHaveCSS('color', 'rgb(139, 234, 125)');
});
import { readFile, writeFile } from 'node:fs/promises';
import { expect, Scrollbars, test, TestTimeouts } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { accessibilityTree, accessibilityNode, moveKeyboardTo } from './accessibility-tree.ts';
import { accessibilityFixture, playwrightVersion } from './accessibility-fixture.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('a complete keyboard journey exposes names, states and each result in Chromium accessibility trees', async ({
  page,
  context,
  browser,
}, artifacts) => {
  const expected = await accessibilityFixture();
  await loadTimedBoard(page);
  const session = await context.newCDPSession(page);
  await session.send('Accessibility.enable');
  const captures: { stage: string; tree: Awaited<ReturnType<typeof accessibilityTree>> }[] = [];
  async function capture(stage: string) {
    const tree = await accessibilityTree(session);
    captures.push({ stage, tree });
    return tree;
  }
  await page.getByRole('combobox', { name: expected.controls.size, exact: true }).focus();
  const controls = await capture('controls');
  expect(accessibilityNode(controls, 'combobox', expected.controls.size).properties.focused).toBe(
    true,
  );
  accessibilityNode(controls, 'button', expected.controls.newGame);
  await page.keyboard.press('Tab');
  expect(
    accessibilityNode(await capture('new-game-control'), 'button', expected.controls.newGame)
      .properties.focused,
  ).toBe(true);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  const closed = await capture('board-entry');
  for (const name of expected.closed) accessibilityNode(closed, 'button', name);
  expect(accessibilityNode(closed, 'button', expected.closed[0]).properties.focused).toBe(true);
  await page.getByRole('status').evaluate((element) => {
    const results: string[] = [];
    element.setAttribute('data-result-history', '[]');
    new MutationObserver(() => {
      results.push(element.textContent ?? '');
      element.setAttribute('data-result-history', JSON.stringify(results));
    }).observe(element, { childList: true, subtree: true, characterData: true });
  });
  for (const [turn, pair] of EXAMPLE_PAIRS.entries()) {
    await moveKeyboardTo(page, pair[0], expected.size);
    await page.keyboard.press('Enter');
    const revealed = await capture(`revealed-${turn + 1}`);
    expect(
      accessibilityNode(revealed, 'button', expected.revealed[pair[0]]).properties.focused,
    ).toBe(true);
    if (turn === 0) await page.clock.runFor(3000);
    await moveKeyboardTo(page, pair[1], expected.size);
    await page.keyboard.press('Space');
    const matched = await capture(`turn-${turn + 1}`);
    for (const index of pair)
      expect(
        accessibilityNode(matched, 'button', expected.matched[index]).properties.disabled,
      ).toBe(true);
    const result = accessibilityNode(matched, 'status');
    expect(result.properties.live).toBe('polite');
    expect(result.properties.atomic).toBe(true);
    expect(result.text).toBe(expected.turns[turn]);
  }
  const win = await capture('completed');
  expect(win.filter((node) => node.role === 'paragraph').map((node) => node.text)).toContain(
    expected.win,
  );
  const announcements: unknown = JSON.parse(
    (await page.getByRole('status').getAttribute('data-result-history')) ?? '[]',
  );
  expect(announcements).toEqual(expected.turns);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  const exit = await capture('board-exit');
  expect(
    accessibilityNode(exit, 'DisclosureTriangle', expected.controls.summary).properties.focused,
  ).toBe(true);
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  const reset = await capture('new-game');
  expect(accessibilityNode(reset, 'button', expected.controls.newGame).properties.focused).toBe(
    true,
  );
  for (const name of expected.closed) accessibilityNode(reset, 'button', name);
  expect(accessibilityNode(reset, 'status').text).toBe(expected.newGame);
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const loadEvents = [
    {
      stage: 'invalid-board',
      field: 'Board code',
      value: 'invalid',
      button: 'Load board',
      notice: 'Invalid board code.',
    },
    {
      stage: 'invalid-snapshot',
      field: 'Snapshot JSON',
      value: '{',
      button: 'Load snapshot',
      notice: 'Invalid snapshot.',
    },
    {
      stage: 'loaded-snapshot',
      field: 'Snapshot JSON',
      value: snapshot,
      button: 'Load snapshot',
      notice: 'Loaded snapshot. Select Resume to continue.',
    },
  ];
  for (const event of loadEvents) {
    await page.getByLabel(event.field, { exact: true }).fill(event.value);
    const button = page.getByRole('button', { name: event.button, exact: true });
    for (let repeat = 1; repeat <= 2; repeat += 1) {
      await button.click();
      await expect(button).toBeFocused();
      await expect(page.locator('.load-notice')).toHaveText(event.notice);
      const tree = await capture(`${event.stage}-${repeat}`);
      const status = accessibilityNode(tree, 'status');
      expect(tree.filter((node) => node.role === 'status')).toHaveLength(1);
      expect(status.properties.live).toBe('polite');
      expect(status.properties.atomic).toBe(true);
      expect(status.text).toBe(event.notice);
    }
  }
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
  // A paused import blocks activation without marking its unmatched cards disabled.
  await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(0);
  expect(
    JSON.parse((await page.getByRole('status').getAttribute('data-result-history')) ?? '[]'),
  ).toEqual([
    ...expected.turns,
    expected.newGame,
    ...loadEvents.flatMap((event) => [event.notice, event.notice]),
  ]);
  const readme = await readFile(new URL('../README.md', import.meta.url), 'utf8');
  expect(readme.split(/\r?\n/)).toContain(expected.readmeRecord);
  const record =
    JSON.stringify(
      {
        schemaVersion: 1,
        status: 'tree-checked',
        chromium: browser.version(),
        playwright: await playwrightVersion(),
        screenReader: null,
        spokenReview: 'User acceptance. No spoken output was tested by the developer.',
        captures,
      },
      null,
      2,
    ) + '\n';
  expect(record).not.toMatch(
    /\b(?:file|https?):\/\/|[A-Za-z]:[\\/]|nodeId|frameId|backendDOMNodeId/,
  );
  await writeFile(artifacts.outputPath('accessibility-journey.json'), record);
  await session.detach();
}, {}, Scrollbars.hidden, TestTimeouts.long);
